SERVE_PY = '''\
"""Generated by `mt ship` — serves the exported model in ./model.

Run locally:  uv run --with-requirements requirements.txt uvicorn serve:app --port 8000
(or, with the requirements installed: uvicorn serve:app --host 0.0.0.0 --port 8000)
"""

from pathlib import Path
from typing import Any

import mlflow.pyfunc
import numpy as np

from mlops_toolbox.core.models import ModelContract
from mlops_toolbox.factories import model_server

_HERE = Path(__file__).parent


class _PyfuncAdapter:
    framework = "mlflow_pyfunc"

    def __init__(self, model: Any) -> None:
        self._model = model

    def predict(self, X: Any) -> np.ndarray:
        return np.asarray(self._model.predict(X))

    def predict_proba(self, X: Any) -> None:
        return None


def build_app() -> Any:
    model = _PyfuncAdapter(mlflow.pyfunc.load_model(str(_HERE / "model")))
    contract_path = _HERE / "contract.json"
    contract = (
        ModelContract.model_validate_json(contract_path.read_text(encoding="utf-8"))
        if contract_path.exists()
        else None
    )
    return model_server().build_app(model, contract=contract)


app = build_app()

if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="0.0.0.0", port=8000)
'''

