def requirements_txt() -> str:
    """Pin the serving dependencies to the versions installed right now."""
    lines = ["mlops-toolbox[deploy,registry]"]
    for package in ("mlflow", "fastapi", "uvicorn", "numpy", "pandas"):
        try:
            lines.append(f"{package}=={metadata.version(package)}")
        except metadata.PackageNotFoundError:
            lines.append(package)
    return "\n".join(lines) + "\n"


