def render_init_file(template: str, project: str) -> str:
    return template.replace("{{project}}", project)


def readme_md(name: str, version: str, has_contract: bool) -> str:
    predict_example = (
        'curl -X POST http://localhost:8000/predict \\\n'
        '  -H "Content-Type: application/json" \\\n'
        "  -d '{\"records\": [{...one object per input column...}]}'\n\n"
        "GET /contract describes the expected columns and types."
        if has_contract
        else 'curl -X POST http://localhost:8000/predict \\\n'
        '  -H "Content-Type: application/json" \\\n'
        "  -d '{\"instances\": [[1.0, 2.0]]}'"
    )
    return f"""\
# {name} (v{version}) — generated by `mt ship`

Self-contained model service: the model artifacts live in `./model`, no
tracking server needed.

## Run locally

With [uv](https://docs.astral.sh/uv/) — no environment setup needed:

```bash
uv run --with-requirements requirements.txt uvicorn serve:app --host 0.0.0.0 --port 8000
```

Or with pip:

```bash
pip install -r requirements.txt
uvicorn serve:app --host 0.0.0.0 --port 8000
```

## Run with Docker

```bash
docker build -t {name}-service .
docker run -p 8000:8000 {name}-service
```

## Predict

```bash
{predict_example}
```
"""
